<section class="wrap flow-card"><span class="flow-icon">◇</span><h1><?= e($t('checkout.title')) ?></h1><p><?= e($t('checkout.desc')) ?></p><?php if($user): $p=$this->plans->get($user['selected_plan_id'],$user['billing_interval'],$user['stripe_mode']); ?><div class="checkout-plan"><p class="payment-mode-label"><?= e($t('billing.payment_mode_'.$p['stripe_mode'])) ?></p><strong><?= e($p['name'].' · '.$p['capacity']) ?></strong><span><?= number_format($p['price_amount']/100,2,$locale==='en'?'.':',','') ?> EUR <?= e($t($p['billing_interval']==='year'?'billing.year.interval':'pricing.interval')) ?></span><p><?= e($t($p['tax_bps']===0?'tax.no_vat':'tax.breakdown',['base'=>number_format($p['price_amount']/100,2,',',''),'rate'=>Zion\BillingTax::percentage($p['tax_bps']),'tax'=>number_format(($p['gross_amount']-$p['price_amount'])/100,2,',',''),'total'=>number_format($p['gross_amount']/100,2,',','')])) ?></p></div><form method="post" action="<?= $url('checkout') ?>"><input type="hidden" name="_csrf" value="<?= e(Zion\Security::csrf()) ?>"><button class="button full"><?= e($t('checkout.button')) ?> ↗</button></form><?php endif ?></section>
